macro_rules! InheritedRefMatchRule {
    () => {
        # [doc = " Variations on RFC 3627's Rule 4: when do reference patterns match against inherited references?"] # [doc = ""] # [doc = " \"Inherited reference\" designates the `&`/`&mut` types that arise from using match ergonomics, i.e."] # [doc = " from matching a reference type with a non-reference pattern. E.g. when `Some(x)` matches on"] # [doc = " `&mut Option<&T>`, `x` gets type `&mut &T` and the outer `&mut` is considered \"inherited\"."] # [derive (Clone , Copy , Debug , PartialEq , Eq)] enum InheritedRefMatchRule { # [doc = " Reference patterns consume only the inherited reference if possible, regardless of whether"] # [doc = " the underlying type being matched against is a reference type. If there is no inherited"] # [doc = " reference, a reference will be consumed from the underlying type."] EatOuter , # [doc = " Reference patterns consume only a reference from the underlying type if possible. If the"] # [doc = " underlying type is not a reference type, the inherited reference will be consumed."] EatInner , # [doc = " When the underlying type is a reference type, reference patterns consume both layers of"] # [doc = " reference, i.e. they both reset the binding mode and consume the reference type."] EatBoth { # [doc = " If `true`, an inherited reference will be considered when determining whether a reference"] # [doc = " pattern matches a given type:"] # [doc = " - If the underlying type is not a reference, a reference pattern may eat the inherited reference;"] # [doc = " - If the underlying type is a reference, a reference pattern matches if it can eat either one"] # [doc = "    of the underlying and inherited references. E.g. a `&mut` pattern is allowed if either the"] # [doc = "    underlying type is `&mut` or the inherited reference is `&mut`."] # [doc = " If `false`, a reference pattern is only matched against the underlying type."] # [doc = " This is `false` for stable Rust and `true` for both the `ref_pat_eat_one_layer_2024` and"] # [doc = " `ref_pat_eat_one_layer_2024_structural` feature gates."] consider_inherited_ref : bool , } , }
    };
}

InheritedRefMatchRule!();